examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
        MonarchPresenceDot(status = status({{people.0.status}}))
        MonarchText(text = {{people.0.name}})
    }
    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
        MonarchPresenceDot(status = status({{people.1.status}}), customStatus = {{people.1.custom.emoji}} + " " + {{people.1.custom.text}})
        MonarchText(text = {{people.1.name}})
    }
    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
        MonarchPresenceDot(status = status({{people.2.status}}))
        MonarchText(text = {{people.2.name}})
    }
    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
        MonarchPresenceDot(status = status({{people.3.status}}), customStatus = {{people.3.custom.text}})
        MonarchText(text = {{people.3.name}})
    }
    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
        MonarchPresenceDot(status = status({{people.4.status}}))
        MonarchText(text = {{people.4.name}})
    }
}

examples.code:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
        MonarchPresenceDot(status = status("online"))
        MonarchText(text = "Ada Lovelace")
    }
    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
        MonarchPresenceDot(status = status("away"), customStatus = "🍽️" + " " + "Lunch")
        MonarchText(text = "Grace Hopper")
    }
    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
        MonarchPresenceDot(status = status("busy"))
        MonarchText(text = "Alan Turing")
    }
    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
        MonarchPresenceDot(status = status("dnd"), customStatus = "Focusing")
        MonarchText(text = "Katherine Johnson")
    }
    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
        MonarchPresenceDot(status = status("offline"))
        MonarchText(text = "Edsger Dijkstra")
    }
}

Box(modifier = Modifier.size(MonarchTheme.spacing.space12).background(MonarchTheme.colors.bgEmphasis, CircleShape)) {
    MonarchPresenceDot(
        status = MonarchPresenceStatus.Online,
        modifier = Modifier.align(Alignment.BottomEnd),
        size = MonarchPresenceDotSize.Lg,
        overlay = true,
    )
}
